-- 327: SG footer -> rework the "Enquires" column.
--   Remove: Trainer Application, Download SSG SOA, Extract CPF Contribution, Class Reschedule.
--   Result order (Contact Us kept at top): Contact Us, Regional Franchisee,
--   Course Development, Corporate On-Site Training, Customised Training,
--   SCTP Program Development, WPL Development.
-- Byte-exact REPLACE on the Enquires <ul> of the SG footer block (block_footer_row2_column5).
-- SG-scoped: the old bytes only exist in the SG footer block, so this is a no-op on
-- partner DBs (MY/GH footers carry different markup / links). Idempotent: once applied,
-- the old bytes are gone and the REPLACE finds nothing to change.
UPDATE cms_block
SET content = REPLACE(content, UNHEX(''), UNHEX(''))
WHERE identifier = 'block_footer_row2_column5'
  AND content LIKE CONCAT('%', UNHEX(''), '%');
